import { gsap } from 'gsap';
import {
  BufferGeometry,
  BufferAttribute,
  InstancedMesh,
  Group,
  Fog,
  IcosahedronGeometry,
  Vector3,
  Color,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { color, uniform, varying, float, vec3, mul, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.userData.animatedInstances || []);
    if (group.userData.particleTimeline) {
      group.userData.particleTimeline.kill();
    }
  };

  // === STAGE BACKDROP ===
  const backdropGeo = new ctx.THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    fog: false,
  });
  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // === FOG ===
  group.fog = new Fog(0x0b0b10, 4, 10);

  // === LIGHTING ===
  const ambientLight = new ctx.THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambientLight);

  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 1.2, 2);
  group.add(keyLight);

  const rimLight = new ctx.THREE.DirectionalLight(0xff6b7a, 0.7);
  rimLight.position.set(-2, -1, -2);
  group.add(rimLight);

  // === PARTICLE CONSTELLATION ===
  // Field particles: 1200 icosahedrons in ellipsoidal shell
  const fieldCount = 1200;
  const coreCount = 90;
  const totalInstances = fieldCount + coreCount;

  const icoGeo = new IcosahedronGeometry(0.012, 1);
  const fieldParticles = new InstancedMesh(icoGeo, null, fieldCount);
  const coreParticles = new InstancedMesh(icoGeo, null, coreCount);

  // Field material: paper white, no metalness, full roughness, self-lit
  const fieldMat = new MeshStandardNodeMaterial({
    color: new Color('#e8ecf2'),
    metalness: 0,
    roughness: 1,
    emissive: new Color('#e8ecf2'),
    emissiveIntensity: 0.9,
    fog: true,
  });

  // Core material: accent red, emissive, will pulse
  const coreMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    metalness: 0,
    roughness: 1,
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    fog: true,
  });

  fieldParticles.material = fieldMat;
  coreParticles.material = coreMat;

  const fieldAnchors = [];
  const coreAnchors = [];
  const depthOpacities = [];

  // Distribute field particles in ellipsoidal shell (6 x 4 x 5 centered at [0,0,-1.5])
  const ellipseA = 3; // semi-major x
  const ellipseB = 2; // semi-major y
  const ellipseC = 2.5; // semi-major z
  const ellipseCenter = new Vector3(0, 0, -1.5);

  for (let i = 0; i < fieldCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 2;
    const r = 0.9 + Math.random() * 0.1; // slight variation in radius

    const x = ellipseA * r * Math.sin(phi) * Math.cos(theta);
    const y = ellipseB * r * Math.sin(phi) * Math.sin(theta);
    const z = ellipseC * r * Math.cos(phi);

    const pos = new Vector3(x, y, z).add(ellipseCenter);
    fieldAnchors.push(pos);

    // Depth falloff: opacity 0.9 at z=0 to 0.15 at z=-5
    const zDepth = pos.z;
    const opacity = 0.9 - (Math.max(0, -zDepth) / 5) * (0.9 - 0.15);
    depthOpacities.push(Math.max(0.15, opacity));

    const matrix = new ctx.THREE.Matrix4();
    matrix.setPosition(pos);
    fieldParticles.setMatrixAt(i, matrix);
  }

  // Distribute core particles in tight sphere (0.5 unit radius at origin)
  for (let i = 0; i < coreCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    const r = 0.5 * Math.random();

    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.sin(phi) * Math.sin(theta);
    const z = r * Math.cos(phi);

    const pos = new Vector3(x, y, z);
    coreAnchors.push(pos);

    const matrix = new ctx.THREE.Matrix4();
    matrix.setPosition(pos);
    coreParticles.setMatrixAt(i, matrix);

    depthOpacities.push(0.9); // core stays visible
  }

  // Add custom uniforms to materials for per-instance depth opacity
  const depthOpacityAttr = new BufferAttribute(
    new Float32Array(depthOpacities),
    1
  );
  icoGeo.setAttribute('depthOpacity', depthOpacityAttr);

  // Override material color nodes to use depth opacity
  const originalFieldColor = fieldMat.colorNode;
  const originalCoreMat = coreMat.colorNode;

  fieldMat.colorNode = mix(
    color(new Color('#e8ecf2')),
    color(new Color('#0b0b10')),
    float(0)
  );

  coreMat.colorNode = mix(
    color(new Color('#ff2a38')),
    color(new Color('#0b0b10')),
    float(0)
  );

  fieldParticles.instanceMatrix.needsUpdate = true;
  coreParticles.instanceMatrix.needsUpdate = true;

  group.add(fieldParticles);
  group.add(coreParticles);

  // Store references for animation
  group.userData.fieldParticles = fieldParticles;
  group.userData.coreParticles = coreParticles;
  group.userData.fieldAnchors = fieldAnchors;
  group.userData.coreAnchors = coreAnchors;
  group.userData.depthOpacities = depthOpacities;
  group.userData.coreMat = coreMat;

  // === TEXT CONTENT ===
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'center',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText(
    'Precision instruments for the dark hours.',
    {
      fontSize: 40,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 600,
    }
  );
  subheadText.position.set(0, 0.5 - 0.75, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2,
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // === PARTICLE EMERGE ANIMATION ===
  const primResult = ctx.primitives['particle-emerge'](fieldParticles, {
    count: fieldCount,
    durationMs: 1400,
  });

  group.userData.particleTimeline = primResult.timeline || null;

  // === AMBIENT DRIFT ===
  const driftTimeline = gsap.timeline({ repeat: -1 });
  group.userData.animatedInstances = [];

  for (let i = 0; i < fieldCount; i++) {
    const anchor = fieldAnchors[i];
    const offsetPhase = Math.random() * Math.PI * 2;
    const driftRadius = 0.04;

    const driftObj = {
      phase: offsetPhase,
      update: () => {
        const matrix = new ctx.THREE.Matrix4();
        const driftX = Math.sin(driftObj.phase) * driftRadius;
        const driftY = Math.cos(driftObj.phase) * driftRadius;
        const pos = new Vector3(
          anchor.x + driftX,
          anchor.y + driftY,
          anchor.z
        );
        matrix.setPosition(pos);
        fieldParticles.setMatrixAt(i, matrix);
      },
    };

    group.userData.animatedInstances.push(driftObj);
    driftTimeline.to(
      driftObj,
      {
        phase: offsetPhase + Math.PI * 2,
        duration: 20,
        ease: 'linear',
        onUpdate: driftObj.update,
      },
      0
    );
  }

  fieldParticles.instanceMatrix.needsUpdate = true;

  // === CORE PULSE ===
  const coreObj = { intensity: 1.8 };
  gsap.timeline({ repeat: -1 }).to(coreObj, {
    intensity: 1.5,
    duration: 5,
    ease: 'sine.inOut',
    onUpdate: () => {
      coreMat.emissiveIntensity = coreObj.intensity;
    },
  });

  group.userData.driftTimeline = driftTimeline;

  return group;
}
